bool ncmm::legacy_character_points_smoke( std::string &error )
{
    using namespace ncmm::legacy_chargen;
    session context;
    if( !active() ) { error = "legacy_points_enable_binding_missing"; return false; }
    context.mode = points::pool::multi;
    avatar sample;
    sample.prof = profession::generic();
    sample.hobbies.clear();
    sample.set_body();
    sample.set_str_base( 8 ); sample.set_dex_base( 8 );
    sample.set_int_base( 8 ); sample.set_per_base( 8 );
    const auto equal_original = [&]() {
        const auto c = calculate( sample );
        return !c.invalid && c.stats == stat_points_used( sample ) &&
               c.traits == trait_points_used( sample ) && c.skills == skill_points_used( sample );
    };
    for( int value = 4; value <= 14; ++value ) {
        sample.set_str_base( value );
        if( !equal_original() ) { error = "legacy_stat_cost_mismatch"; return false; }
    }
    sample.set_str_base( 8 );
    for( const Skill &skill : Skill::skills ) {
        for( int level = 0; level <= 10; ++level ) {
            sample.set_skill_level( skill.ident(), level );
            if( !equal_original() ) { error = "legacy_skill_cost_mismatch"; return false; }
        }
        sample.set_skill_level( skill.ident(), 0 );
    }
    // Both signs and mandatory-trait exemption use actual loaded definitions, not invented IDs.
    int voluntary = 0;
    for( const mutation_branch &trait : mutation_branch::get_all() ) {
        if( !trait.startingtrait || trait.profession || locked( sample, trait.id ) ) continue;
        sample.set_mutation( trait.id );
        const bool equal = equal_original();
        sample.unset_mutation( trait.id );
        if( !equal ) { error = "legacy_trait_cost_mismatch"; return false; }
        if( ++voluntary == 32 ) break;
    }
    if( voluntary == 0 ) { error = "legacy_trait_fixture_missing"; return false; }
    context.cfg = points::config{};
    sample.set_str_base( 14 ); sample.set_dex_base( 14 );
    sample.set_int_base( 14 ); sample.set_per_base( 14 );
    if( valid( sample ) ) { error = "legacy_overspend_not_rejected"; return false; }
    context.mode = points::pool::single;
    if( valid( sample ) ) { error = "legacy_single_overspend_not_rejected"; return false; }
    context.mode = points::pool::freeform;
    if( !valid( sample ) ) { error = "legacy_freeform_was_limited"; return false; }
    context.enabled = false;
    context.mode = points::pool::multi;
    if( !valid( sample ) || limited() ) { error = "disabled_legacy_module_was_active"; return false; }
    return true;
}
